for r in csv.reader(open(VALUES_CSV)):
    if r[0] in (TS,SET):
        vals.setdefault(r[0],{})[r[1].strip()]=r[2]
def daymean(sid,day):
    dev=[]
    for ts,v in vals[TS].items():
        if day=='2018-04-03' or day=='2018-10-17':
            if ts.startswith(day) and int(ts[11:13])>=8 and int(ts[11:13])<=18:
                dev.append(float(v)-float(vals[SET][ts]))
    return sum(dev)/len(dev), len(dev)
